<?php namespace Workspace; $pid=(int)$project['id']; $r=$release; ?>
<p><a href="<?= h(url('project',['id'=>$pid])) ?>">← <?= h($project['title']) ?></a> · <a href="<?= h(url('github',['project'=>$pid])) ?>">GitHub App</a></p>
<section class="panel"><h2>Выпуски проекта</h2><p>Приёмка существующего GitHub Release по точному SHA. Проверка не изменяет GitHub.</p>
<?php if (!$repository || !(int)$repository['active']): ?><p class="planning-warning">Нет активного подключения GitHub App. Доказательства удалённого выпуска недоступны.</p><?php endif ?>
<div class="tablewrap"><table><thead><tr><th>Тег</th><th>SHA</th><th>Состояние</th></tr></thead><tbody><?php foreach($releases as $item): ?><tr><td><a href="<?= h(url('releases',['project'=>$pid,'id'=>$item['id']])) ?>"><?= h($item['tag']) ?></a></td><td><code><?= h($item['commit_sha']) ?></code></td><td><?= h($item['state']) ?></td></tr><?php endforeach ?></tbody></table></div><p>Последние 100 записей.</p></section>
<?php if($r): $rid=(int)$r['id']; $fresh=$r['state']!=='draft'&&$r['verified_at']!==null&&(int)$r['verified_at']>=time()-RELEASE_VERIFY_TTL; $active=$repository&&(int)$repository['active']&&(int)$repository['generation']===(int)$r['repository_generation']; ?>
<section class="panel"><h2><?= h($r['tag']) ?> — <?= h($r['state']) ?></h2><p><a href="<?= h(url('logs',['project'=>$pid,'release'=>$rid])) ?>">Logs этого выпуска</a> · <a href="<?= h(url('incidents',['project'=>$pid,'release'=>$rid])) ?>">Инциденты выпуска</a><?php if($r['state']==='confirmed'): ?> · <a href="<?= h(url('bots',['project'=>$pid,'release'=>$rid])) ?>">Сообщение Bots</a><?php endif ?></p><p>Commit: <code><?= h($r['commit_sha']) ?></code></p><p>Ответственный: #<?= (int)$r['responsible_id'] ?> · Создатель: #<?= (int)$r['creator_id'] ?></p><p>Артефакт: <?= h($r['artifact_name']) ?> · SHA-256: <code><?= h($r['artifact_sha256']) ?></code></p><?php if($r['last_error']!==''): ?><p class="planning-warning">Последняя проверка: <?= h($r['last_error']) ?></p><?php endif ?><h3>Changelog</h3><pre class="release-text"><?= h($r['changelog']) ?></pre><?php if($deliveryRead): ?><p><a href="<?= h(url('delivery',['project'=>$pid,'id'=>$rid])) ?>">Карточка поставки и QA</a></p><?php endif ?><h3>Задачи → PR</h3><ul><?php foreach($releaseTasks as $t): ?><li><a href="<?= h(url('task',['id'=>$t['task_id']])) ?>">Задача #<?= (int)$t['task_id'] ?></a> → PR #<?= (int)$t['pr_number'] ?></li><?php endforeach ?></ul><p>Обязательные checks: <?= h(implode(', ',json_decode($r['required_checks'],true,32,JSON_THROW_ON_ERROR))) ?></p>
<?php if($evidence): ?><h3>Снимок проверки</h3><p><?= h(gmdate('Y-m-d H:i:s',(int)$r['verified_at'])) ?> UTC · <?= $r['state']==='confirmed'?'исторический снимок приёмки':($fresh?'свежий':'исторический, нужна повторная сверка') ?> · SHA-256: <code><?= h($r['evidence_hash']) ?></code></p>
<p><a rel="noreferrer" href="<?= h('https://github.com/'.$repository['full_name'].'/releases/tag/'.rawurlencode($r['tag'])) ?>">GitHub Release #<?= (int)$evidence['release']['id'] ?></a> · Asset #<?= (int)$evidence['artifact']['id'] ?> · <?= (int)$evidence['artifact']['size'] ?> байт</p>
<div class="tablewrap"><table><thead><tr><th>Задача</th><th>PR</th><th>Head SHA</th><th>Merge SHA</th></tr></thead><tbody><?php foreach($evidence['tasks'] as $t): ?><tr><td>#<?= (int)$t['task_id'] ?></td><td><a rel="noreferrer" href="<?= h('https://github.com/'.$repository['full_name'].'/pull/'.$t['pr']['number']) ?>">#<?= (int)$t['pr']['number'] ?></a></td><td><code><?= h($t['pr']['head_sha']) ?></code></td><td><code><?= h($t['pr']['merge_sha']) ?></code></td></tr><?php endforeach ?></tbody></table></div>
<h3>CI точного SHA тега</h3><p>Commit Status: <?= h($evidence['ci']['commit_status']['state']) ?> (<?= (int)$evidence['ci']['commit_status']['count'] ?>)</p><ul><?php foreach($evidence['ci']['checks'] as $c): ?><li><?= h($c['name']) ?> · App #<?= (int)$c['app_id'] ?> · <?= h($c['conclusion']) ?> · check #<?= (int)$c['id'] ?></li><?php endforeach ?></ul><?php endif ?>
<?php if($r['state']==='confirmed'): ?><p><a href="<?= h(url('forum',['project'=>$pid,'kind'=>'release','target'=>$rid])) ?>">Обсуждение выпуска в Forum</a> · <a href="<?= h(url('editorial',['project'=>$pid,'release'=>$rid])) ?>">Редакторский выпуск</a></p><h3>Зафиксированная документация</h3><?php foreach($bookLinks as $link): ?><p><a href="<?= h(url('book',['project'=>$pid,'edition'=>$link['edition_id']])) ?>"><?= h($link['name']) ?> · редакция #<?= (int)$link['edition_id'] ?></a> · SHA-256 <code><?= h($link['snapshot_hash']) ?></code></p><?php endforeach ?><?php if(!$bookLinks): ?><p>Нет доступной закреплённой документации.</p><?php endif ?><p><a href="<?= h(url('book',['project'=>$pid])) ?>">Книги проекта</a></p><p>Подтверждено #<?= (int)$r['confirmed_by'] ?> · <?= h(gmdate('Y-m-d H:i:s',(int)$r['confirmed_at'])) ?> UTC. Историческая приёмка, не гарантия текущего состояния GitHub.</p><?php elseif($releaseManage&&in_array($r['state'],['draft','verified'],true)): ?>
<?php foreach(['release.verify'=>'Проверить GitHub (MFA)','release.confirm'=>'Подтвердить с повторной сверкой (MFA)','release.cancel'=>'Отменить карточку (MFA)'] as $act=>$label): if($act!=='release.cancel'&&!$active)continue; if($act==='release.confirm'&&(!$fresh||$r['state']!=='verified'||(int)$user['id']!==(int)$r['responsible_id']||!$evidence))continue; ?><form method="post" class="inline"><?php formFields($act) ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="id" value="<?= $rid ?>"><input type="hidden" name="version" value="<?= (int)$r['version'] ?>"><button class="<?= $act==='release.cancel'?'secondary':'primary' ?>"><?= h($label) ?></button></form><?php endforeach ?><?php endif ?></section>
<?php endif ?>
<?php if($releaseManage&&$repository&&(int)$repository['active']): ?><section class="panel"><h2>Новая карточка выпуска</h2><p>Выберите завершённые задачи, связанные с PR. Скопируйте точный SHA тега, changelog и SHA-256 артефакта из доверенной сборки. Не более 20 задач.</p><?php if(!$eligible): ?><p>Нет завершённых задач со связью PR.</p><?php else: ?><form method="post"><?php formFields('release.create') ?><input type="hidden" name="project_id" value="<?= $pid ?>">
<label>Тег<input name="tag" required maxlength="100" placeholder="v1.2.3"></label><label>Commit SHA<input name="commit_sha" required pattern="[a-f0-9]{40}" maxlength="40"></label><label>Changelog<textarea name="changelog" required rows="7" maxlength="32000"></textarea></label><label>Имя артефакта<input name="artifact_name" required maxlength="200"></label><label>Ожидаемый SHA-256 артефакта<input name="artifact_sha256" required pattern="[a-f0-9]{64}" maxlength="64"></label><label>Обязательные CI checks (точное имя, по одному в строке)<textarea name="required_checks" required rows="4" maxlength="8000"></textarea></label><label>Ответственный<select name="responsible_id" required><?php foreach($responsibles as $person): ?><option value="<?= (int)$person['id'] ?>"><?= h($person['name']) ?> (#<?= (int)$person['id'] ?>)</option><?php endforeach ?></select></label><fieldset><legend>Задачи выпуска</legend><?php foreach($eligible as $t): ?><label class="release-choice"><input type="checkbox" name="tasks[]" value="<?= (int)$t['id'] ?>"> #<?= (int)$t['id'] ?> <?= h($t['title']) ?> → PR #<?= (int)$t['number'] ?></label><label>Дополнительные PR для задачи #<?= (int)$t['id'] ?><input name="extra_prs[<?= (int)$t['id'] ?>]" maxlength="256" placeholder="например 18, 19"></label><?php endforeach ?></fieldset><button class="primary">Создать карточку (MFA)</button></form><?php endif ?></section><?php endif ?>
